using namespace std;

struct Point {
    int x, y;
    Point(int x, int y) : x(x), y(y) {}
};

long long MOD = 998244353;

int maxMatching(const vector<vector<bool>>& g) {
    int n1 = g.size();
    int n2 = n1 == 0 ? 0 : g[0].size();
    vector<int> match(n2, -1);
    int totalMatches = 0;

    function<bool(int, vector<bool>&)> dfsMatch = [&](int u, vector<bool>& visited) {
        for (int v = 0; v < n2; v++) {
            if (g[u][v] && !visited[v]) {
                visited[v] = true;
                if (match[v] == -1 || dfsMatch(match[v], visited)) {
                    match[v] = u;
                    return true;
                }
            }
        }
        return false;
    };

    for (int u = 0; u < n1; u++) {
        vector<bool> visited(n2, false);
        if (dfsMatch(u, visited))
            totalMatches++;
    }
    return totalMatches;
}

int bruteforce(int n, int m) {
    vector<Point> evenPoints, oddPoints;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if ((i + j) % 2 == 0) {
                evenPoints.emplace_back(i, j);
            } else {
                oddPoints.emplace_back(i, j);
            }
        }
    }
    vector<vector<bool>> adj(evenPoints.size(), vector<bool>(oddPoints.size(), false));
    for (int i = 0; i < (int)evenPoints.size(); i++) {
        for (int j = 0; j < (int)oddPoints.size(); j++) {
            int dist = abs(evenPoints[i].x - oddPoints[j].x) + abs(evenPoints[i].y - oddPoints[j].y);
            if (dist == 3) {
                adj[i][j] = true;
            }
        }
    }
    return 2 * maxMatching(adj);
}

int main() {
