    } else if (n == 3) {
        if (m < 20) {
            cout << bruteforce(n, m) << "\n";
        } else {
            long long res = (long long)n * m;
            if (res % 2 != 0) res--;
            cout << res << "\n";
        }
        return 0;
    }
    long long totalCells = (long long)n * m;
    if (totalCells % 2 != 0) totalCells--;
    cout << totalCells << "\n";
    return 0;
}
